// Jira Webhook -> unser jira_text Format
const root = $json.body || $json;
const issue = root.issue || root;
const F = issue.fields || {};
const nm = o => (o && o.name) ? o.name : "";
const arr = a => Array.isArray(a) ? a : [];
function adf(n){ if(!n) return ""; if(typeof n==="string") return n; let s=n.text||""; if(Array.isArray(n.content)){ for(const c of n.content){ s+=adf(c); } if(n.type==="paragraph"||n.type==="heading") s+="\n"; } return s; }
const desc = (typeof F.description==="string") ? F.description : adf(F.description);
const links = arr(F.issuelinks).map(l=>{
  const t = l.type ? (l.type.outward || l.type.inward || "linked") : "linked";
  const k = (l.outwardIssue && l.outwardIssue.key) || (l.inwardIssue && l.inwardIssue.key) || "";
  return k ? (t + " " + k) : "";
}).filter(Boolean).join("; ");
const lines = [
  "Projekt: " + (F.project ? (F.project.key || F.project.name || "") : ""),
  "Vorgang: " + (issue.key || ""),
  "Zusammenfassung: " + (F.summary || ""),
  "Typ: " + nm(F.issuetype),
  "Status: " + nm(F.status),
  "Prioritaet: " + nm(F.priority),
  "Komponente: " + arr(F.components).map(nm).join(", "),
  "Loesung: " + nm(F.resolution),
  "Labels: " + arr(F.labels).join(", "),
  "Autor: " + (F.reporter ? (F.reporter.displayName || "") : ""),
  "Bearbeiter: " + (F.assignee ? (F.assignee.displayName || "") : "Nicht zugewiesen"),
  "Erstellt: " + (F.created || ""),
  "Aktualisiert: " + (F.updated || ""),
  "Loesungsversion(en): " + (arr(F.fixVersions).map(nm).join(", ") || "Keine"),
  "Betrifft Version(en): " + (arr(F.versions).map(nm).join(", ") || "Keine"),
  "Verknuepfungen: " + links,
  "Beschreibung:",
  desc
];
return [{ json: { jira_text: lines.join("\n"), target_language: "both", country: "DE", division: "", user_group: "biz", whitelist: "oneSCM, ONESCM, DOT ONESCM, DOT, oneSCM Team, SCM, Supply Chain, Dify, Jira, Jira Cloud, Confluence, Xray, Xray Test Repository, n8n, Program Increment, Sprint, Epic, Backlog, Story, Vehicle Management, Documents & Communications, Product Management, Order Management, Contract Generation, Contract Preview, Contract Preview PDF, Service Contract, Master Template, Vehicle Group, Vehicle Groups, Vehicle Identifier, Success Flow, Business Flow, Baumuster, Baureihe, Chassis, Chassis Number, Model Code, Order Number, First Registration, First Registration date, VIN, FIN, Licence Plate, Built to order, Built to stock, Build to order, Build to stock, BTO, BTS, Aftersales, After Sales, Spare Parts, Warranty, Homologation, Telematics, Fleet, Dealer, Retail, Werk, Mercedes-Benz, Mercedes-Benz AG, Daimler, Daimler Truck, Releaseletter, Release Letter, PI, PI TBD, PI14, PI15, PI16, Toggle, Template, Preview, PDF, Workflow, API, URL, ID, SLA, KPI, ADF", issue_key: issue.key || "" } }];

// Extract & Prepare — deterministic Jira parsing + guardrails (no LLM)
const inp = $json;
const text = String(inp.jira_text || "");
const defs = [
  ["ticket", /(?:Vorgang|Ticket|Issue|Key)\s*[:\-]\s*([A-Z][A-Z0-9]+-\d+)/i],
  ["summary", /(?:Zusammenfassung|Summary|Titel|Title)\s*[:\-]\s*(.+)/i],
  ["typ", /(?:Vorgangstyp|Issue\s*Type|Typ|Type)\s*[:\-]\s*(.+)/i],
  ["status", /(?:^|\n)\s*Status\s*[:\-]\s*(.+)/i],
  ["prioritaet", /(?:Priorit(?:ä|ae)t|Priority)\s*[:\-]\s*(.+)/i],
  ["projekt", /(?:Projekt|Project)\s*[:\-]\s*(.+)/i],
  ["komponente", /(?:Komponenten?|Components?)\s*[:\-]\s*(.+)/i],
  ["resolution", /(?:L(?:ö|oe)sung|Resolution)\s*[:\-]\s*(.+)/i],
  ["labels", /(?:Labels?|Stichw(?:ö|oe)rter|Beschriftungen)\s*[:\-]\s*(.+)/i],
  ["autor", /(?:Autor|Reporter|Ersteller)\s*[:\-]\s*(.+)/i],
  ["bearbeiter", /(?:Bearbeiter|Assignee|Zugewiesen an)\s*[:\-]\s*(.+)/i],
  ["erstellt", /(?:Erstellt|Created)\s*[:\-]\s*(.+)/i],
  ["aktualisiert", /(?:Aktualisiert|Updated|Ge(?:ä|ae)ndert)\s*[:\-]\s*(.+)/i],
  ["fixversion", /(?:Fix[- ]?Versions?|L(?:ö|oe)sungsversion(?:\(en\)|en)?)\s*[:\-]\s*(.+)/i],
  ["affected", /(?:Betrifft Version(?:\(en\)|en)?|Affects?\s*Versions?|Betroffene Version(?:en)?)\s*[:\-]\s*(.+)/i],
  ["verknuepfungen", /(?:Verkn(?:ü|ue)pfungen|Linked issues|Links)\s*[:\-]\s*(.+)/i],
];
const f = {};
for (const [k, re] of defs) { const m = text.match(re); if (m && m[1]) f[k] = m[1].trim(); }
const isNone = v => !v || /keine|none/i.test(v);
const noVer = isNone(f.fixversion) && isNone(f.affected);
const pi_label = noVer ? "PI TBD" : (f.fixversion || f.affected);
const report_date = f.erstellt || "unbekannt (Quelle pruefen)";
const linked = (f.verknuepfungen || "").match(/[A-Z]+-\d+/g) || [];
const linked_ids = [...new Set(linked)].sort().join(", ");
const typ = f.typ || "";
const typ_norm = /test/i.test(typ) ? "Testfall / Validierung" : (typ || "unbekannt");
const sec = n => { const m = text.match(new RegExp(n + "\\s*[:\\-]\\s*([^\\n]+)", "i")); return m ? m[1].trim() : ""; };
const desc = { current: sec("Current State"), target: sec("Target State"), flow: sec("Business Flow"), extra: sec("Extra Details"), accept: sec("Acceptance Criteria") };
const pii = [];
if (/\b[\w.+-]+@[\w-]+\.[\w.-]+\b/.test(text)) pii.push("E-Mail");
if (/\b[A-HJ-NPR-Z0-9]{17}\b/.test(text)) pii.push("FIN/VIN");
if (/\b[A-ZÄÖÜ]{1,3}-[A-Z]{1,2}\s?\d{1,4}\b/.test(text)) pii.push("Kennzeichen");
for (const n of [f.autor, f.bearbeiter]) { if (n && !/nicht zugewiesen|unassigned/i.test(n)) pii.push("Name: " + n); }
const pii_found = pii.length ? pii.join("; ") : "keine";
const L = [];
const add = (lab, v) => { if (v) L.push("- " + lab + ": " + v); };
add("Referenz", f.ticket); add("Titel", f.summary);
add("Vorgangstyp (wahrheitsgemaess)", typ_norm); add("Status (woertlich)", f.status);
add("Prioritaet", f.prioritaet); add("Projekt", f.projekt);
add("Komponente", f.komponente); add("Resolution", f.resolution);
add("Labels", f.labels); add("Release/Version", pi_label);
add("Datum (aus 'Erstellt')", report_date);
add("Aktueller Zustand", desc.current); add("Zielzustand", desc.target);
add("Ablauf", desc.flow); add("Zusaetzliche Details", desc.extra); add("Abnahmekriterien", desc.accept);
const facts = L.join("\n");
const ug = { mgmt: "Management: Kurzfassung, nur belegte Fakten, keine Marketing-Aussagen.", biz: "Fachbereich: sachlich, ausgewogen.", it: "IT/Entwicklung: technische Metadaten inkl. Labels/Komponente.", end: "Endanwender: einfache Sprache, minimale Metadaten." };
const guidance = "Land " + (inp.country || "DE") + ", Sparte " + (inp.division || "-") + " - " + (ug[inp.user_group] || ug.biz);
const w = [];
if (/test/i.test(typ)) w.push("Quelle ist Typ 'Test' -> nicht als Feature darstellen.");
if (noVer) w.push("Keine Version in Quelle -> PI TBD, keine PI erfinden.");
if (linked_ids) w.push("Verlinkte Tickets NICHT als Inhalt/Scope: " + linked_ids);
if (pii_found !== "keine") w.push("Personenbezogene Daten vorhanden -> anonymisieren: " + pii_found);
const warnings = w.length ? w.map(x => "- " + x).join("\n") : "- keine";

// --- Whitelist: Produkt-/Fachbegriffe, die unveraendert bleiben muessen ---
const WL_DEFAULT = "oneSCM, ONESCM, DOT ONESCM, DOT, oneSCM Team, SCM, Supply Chain, Dify, Jira, Jira Cloud, Confluence, Xray, Xray Test Repository, n8n, Program Increment, Sprint, Epic, Backlog, Story, Vehicle Management, Documents & Communications, Product Management, Order Management, Contract Generation, Contract Preview, Contract Preview PDF, Service Contract, Master Template, Vehicle Group, Vehicle Groups, Vehicle Identifier, Success Flow, Business Flow, Baumuster, Baureihe, Chassis, Chassis Number, Model Code, Order Number, First Registration, First Registration date, VIN, FIN, Licence Plate, Built to order, Built to stock, Build to order, Build to stock, BTO, BTS, Aftersales, After Sales, Spare Parts, Warranty, Homologation, Telematics, Fleet, Dealer, Retail, Werk, Mercedes-Benz, Mercedes-Benz AG, Daimler, Daimler Truck, Releaseletter, Release Letter, PI, PI TBD, PI14, PI15, PI16, Toggle, Template, Preview, PDF, Workflow, API, URL, ID, SLA, KPI, ADF";
const whitelist = [...new Set(String(inp.whitelist || WL_DEFAULT).split(/[,;\n]+/).map(s => s.trim()).filter(Boolean))].join(", ");

const sys_de = [
"Du bist Release-Redakteur fuer oneSCM. Erstelle einen deutschen Releaseletter AUSSCHLIESSLICH aus den belegten Fakten. Erfinde nichts.",
"HARTE REGELN:",
"1) DATUM: nutze ausschliesslich " + report_date + " (Jira 'Erstellt'). Niemals das heutige/Laufdatum.",
"2) VERSION: nutze ueberall " + pi_label + ". Erfinde keine Quartals-/PI-Version.",
"3) UMFANG: Inhalt ist NUR der referenzierte Vorgang. Verlinkte Tickets (" + (linked_ids || "keine") + ") NICHT als eigene Zeilen aufnehmen.",
"4) STATUS & TYP: Status woertlich. Typ wahrheitsgemaess (Test -> 'Testfall/Validierung', nie 'Feature'). Nicht belegte Nutzenaussagen mit '[redaktionell]' kennzeichnen.",
"5) DATENSCHUTZ: keine personenbezogenen Daten. Verfasser immer 'oneSCM Team'. Vorpruefung: " + pii_found + ".",
"6) PRODUKTBEGRIFFE: Lasse die folgenden Begriffe EXAKT und UNVERAENDERT (nicht uebersetzen, nicht umformulieren, nicht abkuerzen): " + whitelist,
"ZIELGRUPPE: " + guidance,
"PRUEFHINWEISE:\n" + warnings
].join("\n");
const usr_de = "FAKTEN (belegt aus Jira):\n" + facts;
const sys_en = "Translate the German release letter into precise professional English. Keep ALL facts, numbers, IDs, dates and the version label identical. Keep the following product/domain terms EXACTLY as written, do not translate or rephrase them: " + whitelist + ". Keep '[redaktionell]' as '[editorial]'. Do not add or remove content.";
const sys_sum = "Fasse den Ticket-Inhalt neutral und belegt zusammen. Erfinde nichts. Lasse die Produktbegriffe (" + whitelist + ") unveraendert. Gib genau aus:\nDE: <2-3 Saetze>\nEN: <2-3 sentences>";
const usr_sum = "FAKTEN:\n" + facts + "\nVersion: " + pi_label + " | Datum: " + report_date + " | Verlinkt (nicht Inhalt): " + (linked_ids || "keine");

return [{ json: { facts, pi_label, report_date, linked_ids: linked_ids || "keine", pii_found, guidance, warnings, whitelist, target_language: inp.target_language || "both", sys_de, usr_de, sys_en, sys_sum, usr_sum } }];

// Merge & PII-Scrub — safety net after the LLMs
const path = o => { try { return o.choices[0].message.content; } catch(e){ try { return o.content[0].text; } catch(e2){ return ""; } } };
let de = path($('LLM Releaseletter DE').item.json) || "";
let en = path($('LLM Uebersetzung EN').item.json) || "";
let sum = path($('LLM Zusammenfassung').item.json) || "";
const P = [
  [/\b[\w.+-]+@[\w-]+\.[\w.-]+\b/g, "[E-Mail entfernt]", "E-Mail"],
  [/\b[A-HJ-NPR-Z0-9]{17}\b/g, "[FIN/VIN entfernt]", "FIN/VIN"],
  [/\b[A-ZÄÖÜ]{1,3}-[A-Z]{1,2}\s?\d{1,4}\b/g, "[Kennzeichen entfernt]", "Kennzeichen"],
  [/\b[Uu](?:ID|SR)?\d{5,}\b/g, "[User-ID entfernt]", "User-ID"],
];
const hits = new Set();
const scrub = t => { let s = t; for (const [re, rep, lab] of P) { if (re.test(s)) { hits.add(lab); s = s.replace(re, rep); } } return s; };
de = scrub(de); en = scrub(en); sum = scrub(sum);
const ex = $('Extract & Prepare').item.json;
return [{ json: {
  releaseletter_de: de,
  releaseletter_en: en,
  zusammenfassung: sum,
  fakten: ex.facts,
  warnungen: ex.warnings,
  pii_entfernt: hits.size ? [...hits].join(", ") : "keine"
} }];
